package dev.kuan.kuanperion;
import dev.kuan.kuanperion.automation.*;import java.util.*;import java.util.function.*;
/** Actual controller/session/ledgers with controlled native state, not a real Bazaar purchase. */
public final class BazaarPurchaseControllerTest {
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 static final class Game implements BazaarPurchaseController.Game {
  Object level=new Object(),container=new Object();boolean available=true,safe=true,empty=true;int sends;boolean throwSend,rejectSend;Runnable onRead=()->{},onSend=()->{};
  Map<Integer,ItemSnapshot> inventory=BazaarPurchaseViewTest.inventory();MenuSnapshot menu=BazaarPurchaseViewTest.menu("Wheat",12,"Buy 64x Wheat",List.of("Price: 128 coins"));
  public boolean available(){return available;}public boolean safe(){return safe;}public boolean cursorEmpty(){return empty;}public Object level(){return level;}public Object menuIdentity(){return container;}
  public Map<Integer,ItemSnapshot> inventory(){onRead.run();return Map.copyOf(inventory);}public MenuSnapshot menu(long world){return menu;}
  public GuardedMenuAction.Result purchase(AutomationCoordinator c,AutomationCoordinator.Lease lease,MenuContract contract,MenuContract.Ticket ticket,Supplier<AutomationContext> context,Supplier<MenuSnapshot> menus,long now){return GuardedMenuAction.perform(c,lease,contract,ticket,GuardedMenuAction.Space.REQUIRE_FREE_SLOT,context,menus,t->{sends++;onSend.run();if(throwSend)throw new IllegalStateException("native uncertain");return !rejectSend;},now);}
 }
 static final class H {
  final Game g=new Game();final AutomationCoordinator coordinator=new AutomationCoordinator();final InventoryReceipts items=new InventoryReceipts();final CursorReceipts cursors=new CursorReceipts();final SpendingBudget budget;final BazaarAcquisitionPlan.Plan plan;
  boolean farming=true;long world=1,now=1;Set<AutomationContext.Blocker> blockers=Set.of();final AutomationSession session=new AutomationSession(coordinator,this::context,()->{},()->farming=false);final AutomationSession.Handle h;final InventoryReceipts.Stamp opening;final CursorReceipts.OpeningStamp cursorOpening;BazaarPurchaseController controller;
  AutomationContext context(){return new AutomationContext(world,farming,true,blockers);}
  H(AutomationFeature feature){this(feature,1000);}
  H(AutomationFeature feature,long cap){budget=new SpendingBudget(cap);plan=BazaarPurchaseViewTest.plan(budget,64);h=session.begin(feature,0,60_000_000_000L);check(h!=null,"root fixture");opening=items.stamp(1);cursorOpening=cursors.openingStamp(1,0);blockers=Set.of(AutomationContext.Blocker.MENU);applyMenu();cursors.observe(1,2,BazaarPurchaseViewTest.inventory().get(0),1);controller=make(budget);}
  BazaarPurchaseController make(SpendingBudget used){return new BazaarPurchaseController(coordinator,session,this::context,items,cursors,new BazaarPurchaseController.Purchase(h,plan,plan.requests().getFirst(),used,1000,opening,cursorOpening),g,()->now);}
  void applyMenu(){for(var slot:g.menu.slots())if(!slot.playerInventory())items.observe(1,2,slot.index(),slot.item());}
  void deliver(boolean bothAliases,boolean cursor){
   now=2;var wheat=new ItemSnapshot("WHEAT","minecraft:wheat","","Wheat","wheat",64,List.of(),false);g.inventory.put(9,wheat);var slots=new ArrayList<>(g.menu.slots());slots.set(27,new MenuSnapshot.Slot(27,wheat,true));g.menu=new MenuSnapshot(1,2,5,"Wheat",27,slots);items.observe(1,0,9,wheat);if(bothAliases)items.observe(1,2,27,wheat);if(cursor)cursors.observe(1,2,g.inventory.get(0),now);
  }
 }
 public static void runNativeFixtures(){
  var components=net.minecraft.core.component.DataComponentMap.builder().set(net.minecraft.core.component.DataComponents.ITEM_NAME,net.minecraft.network.chat.Component.literal("Fixture")).set(net.minecraft.core.component.DataComponents.MAX_STACK_SIZE,64).build();
  var stack=new net.minecraft.world.item.ItemStack(net.minecraft.core.Holder.direct(net.minecraft.world.item.Items.GOLD_NUGGET,components),1,net.minecraft.core.component.DataComponentPatch.EMPTY);stack.set(net.minecraft.core.component.DataComponents.CUSTOM_NAME,net.minecraft.network.chat.Component.literal("Buy 64x Wheat"));stack.set(net.minecraft.core.component.DataComponents.LORE,new net.minecraft.world.item.component.ItemLore(List.of(net.minecraft.network.chat.Component.literal("Price: 128 coins"))));
  var raw=AutomationGameView.item(stack,false);var base=BazaarPurchaseViewTest.menu("Wheat",12,"Buy 64x Wheat",List.of("Price: 128 coins"));var slots=new ArrayList<>(base.slots());slots.set(12,new MenuSnapshot.Slot(12,raw));var menu=new MenuSnapshot(1,2,4,base.title(),27,slots);
  check(BazaarPurchaseView.inspect(menu,BazaarPurchaseViewTest.plan(new SpendingBudget(1000),64).requests().getFirst()).isPresent(),"actual26.2 native name/lore/component projection enters legacy quote parser");
  stack.set(net.minecraft.core.component.DataComponents.CUSTOM_NAME,net.minecraft.network.chat.Component.literal("Buy 63x Wheat"));check(raw.name().equals("Buy 64x Wheat"),"native item mutation cannot mutate earlier immutable quote");
  slots.set(12,new MenuSnapshot.Slot(12,AutomationGameView.item(stack,false)));check(BazaarPurchaseView.inspect(new MenuSnapshot(1,2,5,base.title(),27,slots),BazaarPurchaseViewTest.plan(new SpendingBudget(1000),64).requests().getFirst()).isEmpty(),"native projected wrong quantity refuses");
  System.out.println("BazaarPurchaseViewNativeTest: PASS actual26.2 component fixtures; no client/server purchase");
 }
 public static void main(String[]args){
  for(var f:List.of(AutomationFeature.PEST,AutomationFeature.COMPOSTER,AutomationFeature.VISITOR,AutomationFeature.SUPERCRAFT)){
   var x=new H(f);check(x.controller.buy(1)==GuardedMenuAction.Result.SENT&&x.g.sends==1&&x.budget.available()==872,"one native guarded purchase reserves original budget: "+f);check(x.controller.buy(1)==GuardedMenuAction.Result.REJECTED&&x.g.sends==1,"never resend");x.deliver(true,true);x.controller.onSystemMessage(1,"[Bazaar] Bought 64x Wheat for 128 coins!");x.controller.poll(2);check(x.controller.state()==BazaarPurchaseController.State.CONFIRMED&&x.budget.spent()==128&&x.session.isCurrent(x.h)&&x.session.holdsFarming()&&x.farming,"exact dual receipt/cursor/GAME cost, parent and Farm stay held: "+f);
  }
  for(long limit:List.of(128L,200L)){var exact=new H(AutomationFeature.VISITOR,limit);check(exact.controller.buy(1)==GuardedMenuAction.Result.SENT&&exact.g.sends==1&&exact.budget.available()==limit-128,"own reservation must not invalidate the exact immutable quote at final native guard: "+limit);}
  for(String mode:List.of("foreign-budget","inventory","missing-menu-receipt","cursor","world","level","container","manual","unavailable","farm-off","expired","lease-lost","cancel-on-read")){
   var x=new H(AutomationFeature.VISITOR);
   switch(mode){case "foreign-budget"->x.controller=x.make(new SpendingBudget(1000));case "inventory"->x.g.inventory.put(40,new ItemSnapshot("STONE","minecraft:stone","","Stone","stone",1,List.of(),true));case "missing-menu-receipt"->x.items.clear();case "cursor"->x.g.empty=false;case "world"->x.world=2;case "level"->x.g.level=new Object();case "container"->x.g.container=new Object();case "manual"->x.g.safe=false;case "unavailable"->x.g.available=false;case "farm-off"->x.farming=false;case "expired"->x.now=60_000_000_000L;case "lease-lost"->x.coordinator.release(x.h.lease());case "cancel-on-read"->x.g.onRead=()->x.session.invalidate();}
   check(x.controller.buy(x.now)==GuardedMenuAction.Result.REJECTED&&x.g.sends==0&&x.budget.available()==1000,"no native send or budget hold: "+mode);
  }
  var x=new H(AutomationFeature.BOOK_COMBINE);check(x.controller.buy(1)==GuardedMenuAction.Result.REJECTED&&x.g.sends==0,"foreign feature cannot borrow buyer");
  x=new H(AutomationFeature.VISITOR);x.g.rejectSend=true;check(x.controller.buy(1)==GuardedMenuAction.Result.REJECTED&&x.budget.available()==1000,"definite native rejection releases reservation");
  x=new H(AutomationFeature.VISITOR);x.g.throwSend=true;check(x.controller.buy(1)==GuardedMenuAction.Result.UNCERTAIN&&x.budget.available()==872,"unknown native outcome retains possible spend");x.controller.cancel();check(x.budget.available()==872&&x.session.isCurrent(x.h),"child cancellation never refunds uncertainty or releases parent");
  x=new H(AutomationFeature.VISITOR);x.controller.buy(1);x.deliver(false,true);x.controller.onSystemMessage(1,"[Bazaar] Bought 64x Wheat for 128 coins!");x.controller.poll(2);check(x.controller.state()==BazaarPurchaseController.State.AWAITING,"single alias cannot prove purchase");
  x=new H(AutomationFeature.VISITOR);x.controller.buy(1);x.deliver(true,false);x.controller.onSystemMessage(1,"[Bazaar] Bought 64x Wheat for 128 coins!");x.controller.poll(2);check(x.controller.state()==BazaarPurchaseController.State.AWAITING,"missing fresh empty cursor cannot prove purchase");
  x=new H(AutomationFeature.VISITOR);x.controller.buy(1);x.deliver(true,true);x.controller.poll(2);check(x.controller.state()==BazaarPurchaseController.State.AWAITING,"inventory alone cannot prove coin cost");x.controller.onSystemMessage(2,"[Bazaar] Bought 64x Wheat for 128 coins!");x.controller.poll(2);check(x.controller.state()==BazaarPurchaseController.State.AWAITING,"foreign world receipt ignored");x.coordinator.release(x.h.lease());x.controller.onSystemMessage(1,"[Bazaar] Bought 64x Wheat for 128 coins!");x.controller.poll(2);check(x.controller.state()==BazaarPurchaseController.State.UNCERTAIN&&x.budget.spent()==0,"lost original lease cannot confirm stale session handle");
  x=new H(AutomationFeature.VISITOR);var beforeNative=x;var reads=new int[]{0};x.g.onRead=()->{if(++reads[0]==2)beforeNative.g.inventory.put(40,new ItemSnapshot("STONE","minecraft:stone","","Stone","changed",1,List.of(),true));};check(x.controller.buy(1)==GuardedMenuAction.Result.REJECTED&&x.g.sends==0&&x.budget.available()==1000,"full43 drift at final structural menu read refuses and releases definite non-spend");
  x=new H(AutomationFeature.VISITOR);var changedQuote=x;var priceReads=new int[]{0};x.g.onRead=()->{if(++priceReads[0]==2)changedQuote.g.menu=BazaarPurchaseViewTest.menu("Wheat",12,"Buy 64x Wheat",List.of("Price: 256 coins"));};check(x.controller.buy(1)==GuardedMenuAction.Result.REJECTED&&x.g.sends==0&&x.budget.available()==1000,"immutable whole-menu quote check still rejects changed cost after reservation");
  x=new H(AutomationFeature.VISITOR);var reentrant=x;x.g.onSend=()->reentrant.controller.cancel();check(x.controller.buy(1)==GuardedMenuAction.Result.UNCERTAIN&&x.g.sends==1&&x.budget.available()==872,"cancellation during native callback cannot become success or replay");
  x=new H(AutomationFeature.VISITOR);x.controller.buy(1);x.deliver(true,true);x.controller.onSystemMessage(1,"[Bazaar] Bought 64x Wheat for 128 coins!");var duringRead=x;x.g.onRead=()->duringRead.controller.cancel();x.controller.poll(2);check(x.controller.state()==BazaarPurchaseController.State.UNCERTAIN&&x.budget.spent()==0,"completion read cancellation cannot be overwritten by confirmation");
  x=new H(AutomationFeature.VISITOR);x.controller.buy(1);x.deliver(true,true);var replaced=x;var foreign=new AutomationCoordinator.Lease[1];x.g.onRead=()->{replaced.g.onRead=()->{};replaced.session.invalidate();replaced.world=2;replaced.blockers=Set.of();foreign[0]=replaced.coordinator.tryAcquire(AutomationFeature.STASH,replaced.context(),2,60_000_000_000L);};x.controller.poll(2);check(x.controller.state()==BazaarPurchaseController.State.UNCERTAIN&&foreign[0]!=null&&x.coordinator.holdsIdentity(foreign[0]),"old completion read cannot clear a new-world Stash lease");
  System.out.println("BazaarPurchaseControllerTest: PASS (actual terminal buyer/original shared budget/real parent and receipt ledgers, controlled native state; no opener/navigation/parent caller/live claim)");
 }
}
